insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('peru-assado-tradicional', 1, 'Peru assado tradicional', 'salgado', 'carnes-e-pratos-principais', 'principal', '6 a 8 pessoas', 8, '30 min + 12 a 24 h de marinada', '2h30 a 3h30 (cerca de 40 min por kg)', '["Bata alho, cebola, sucos, mostarda, vinho, sal e pimenta.","Coloque o peru em recipiente adequado, espalhe a marinada e acrescente louro e alecrim. Deixe na geladeira por 12 a 24 horas, seguindo as orientações de descongelamento e conservação.","Retire da marinada, seque levemente e espalhe manteiga sobre a pele e, com cuidado, sob a pele do peito.","Coloque em assadeira, cubra com papel-alumínio e asse conforme o peso e as instruções do fabricante.","Retire o papel no final para dourar, regando com o caldo da assadeira.","Confira a temperatura interna de segurança antes de servir e deixe descansar por alguns minutos."]'::jsonb, '["Se o peru vier com termômetro pop-up, use-o só como referência e confirme com termômetro culinário.","Peru temperado de fábrica já tem sal: reduza ou dispense o sal da receita."]'::jsonb, '["Vinho branco: mesma quantidade de caldo de legumes com 2 colheres de vinagre.","Manteiga: margarina ou azeite."]'::jsonb, 'Sobras na geladeira em até 2 horas após servir, por até 3 dias. Congela por até 3 meses, desossado.', 'Escala por tamanho comercial da ave; não multiplicar como carne sem osso. Confirmar peso e instruções do fabricante.', 'fotos/peru-assado-tradicional.webp', 'rascunho');
insert into recipe_ingredients (recipe_id, ingredient_id, qty, unit, note, grp, sort, scale_rule) select 'peru-assado-tradicional', id, 1, 'un', 'aprox. 4 kg a 4,5 kg, descongelado conforme a embalagem', null, 0, 'peca_inteira' from ingredients where name = 'Peru';
insert into recipe_ingredients (recipe_id, ingredient_id, qty, unit, note, grp, sort, scale_rule) select 'peru-assado-tradicional', id, 6, 'dente', null, null, 1, 'linear' from ingredients where name = 'Alho';
