insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('chester-assado', 2, 'Chester assado', 'salgado', 'carnes-e-pratos-principais', 'principal', '6 a 8 pessoas', 8, '20 min (+ descongelamento)', '1h30 a 2h, conforme o peso', '["Misture alho, manteiga, suco de laranja, limão, mostarda, páprica, sal e pimenta.","Espalhe o tempero sobre toda a ave e deixe na geladeira por algumas horas.","Coloque a cebola e o alecrim na cavidade, se desejar.","Disponha em assadeira, cubra com papel-alumínio e asse conforme o peso e as instruções da embalagem.","Retire o papel na etapa final e regue com o próprio caldo até dourar.","Verifique o cozimento completo antes de servir."]'::jsonb, '["Chester já vem temperado: prove o molho antes de pôr sal.","Deixe descansar 15 minutos antes de fatiar para não perder suco."]'::jsonb, '["Cerveja: caldo de frango ou mais suco de laranja.","Amido: farinha de trigo (1 colher e meia)."]'::jsonb, 'Geladeira por até 3 dias; congela fatiado por até 3 meses.', 'Ave temperada comercialmente pode conter sal. Priorizar temperatura interna segura de 74 °C.', 'fotos/chester-assado.webp', 'rascunho');
insert into recipe_ingredients (recipe_id, ingredient_id, qty, unit, note, grp, sort, scale_rule) select 'chester-assado', id, 1, 'un', 'aprox. 3 kg a 3,5 kg', null, 0, 'peca_inteira' from ingredients where name = 'Chester';
