insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('pernil-suino-assado', 3, 'Pernil suíno assado', 'salgado', 'carnes-e-pratos-principais', 'principal', '8 a 10 pessoas', 10, '20 min + 8 a 12 h de marinada', '2h30 a 3h', '["Bata alho, cebola, limão, laranja, vinho, azeite, sal e pimenta.","Faça pequenos furos na carne e distribua a marinada por toda a peça.","Acrescente louro e alecrim, tampe e deixe na geladeira por 12 a 24 horas.","Transfira para uma assadeira com a marinada e cubra com papel-alumínio.","Asse em temperatura moderada, regando periodicamente com o caldo.","Retire o papel para dourar e confirme que o centro da peça atingiu temperatura segura."]'::jsonb, '["Com osso ou sem osso funciona; sem osso fica mais fácil de fatiar.","Use termômetro em vez de deixar mais tempo no forno."]'::jsonb, '["Vinho branco: suco de laranja.","Pernil com osso: compre cerca de 30% a mais de peso."]'::jsonb, 'Geladeira por até 4 dias. Ótimo para sanduíche no dia seguinte.', 'Com osso, comprar mais peso e calcular rendimento comestível; tempo depende do formato e forno.', 'fotos/pernil-suino-assado.webp', 'rascunho');
