insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('lombo-suino-ao-molho-de-laranja', 4, 'Lombo suíno ao molho de laranja', 'salgado', 'carnes-e-pratos-principais', 'principal', '6 pessoas', 6, '15 min + 2 a 4 h de marinada', '50 min a 1h', '["Tempere o lombo com alho, cebola, limão, azeite, alecrim, sal e pimenta.","Deixe marinar na geladeira por pelo menos 4 horas.","Coloque em assadeira, cubra e asse até ficar cozido.","Retire a cobertura e deixe dourar, sem ressecar a carne.","Para o molho, leve o suco de laranja e o mel ao fogo.","Adicione o amido dissolvido na água e mexa até engrossar. Finalize com manteiga.","Fatie o lombo e sirva com o molho."]'::jsonb, '["Lombo resseca fácil: use termômetro em vez de deixar mais tempo no forno."]'::jsonb, '["Mel: açúcar mascavo.","Mostarda: pode omitir."]'::jsonb, 'Geladeira por até 3 dias, com o molho separado.', 'Não prolongar forno apenas por peso: usar termômetro e espessura da peça.', 'fotos/lombo-suino-ao-molho-de-laranja.webp', 'rascunho');
