insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('tender-natalino-com-abacaxi', 5, 'Tender natalino com abacaxi', 'salgado', 'carnes-e-pratos-principais', 'principal', '6 pessoas', 6, '15 min', '40 min a 1h, conforme a embalagem', '["Faça cortes superficiais em losangos na superfície do tender.","Misture mel, mostarda, suco de laranja e açúcar mascavo.","Coloque o tender em assadeira e pincele com parte do molho.","Asse conforme as instruções da embalagem, regando periodicamente.","Nos minutos finais, distribua o abacaxi e pincele novamente.","Deixe caramelizar levemente e sirva fatiado."]'::jsonb, '["O tender já vem cozido: o forno é só para aquecer e caramelizar. Não precisa de sal."]'::jsonb, '["Abacaxi em calda escorrido no lugar do fresco.","Cravo: pode omitir."]'::jsonb, 'Geladeira por até 5 dias, bem embrulhado.', 'Tender costuma ser pré-cozido e salgado; seguir embalagem e evitar acrescentar sal.', 'fotos/tender-natalino-com-abacaxi.webp', 'rascunho');
insert into recipe_ingredients (recipe_id, ingredient_id, qty, unit, note, grp, sort, scale_rule) select 'tender-natalino-com-abacaxi', id, 1, 'un', 'aprox. 1 kg', null, 0, 'peca_inteira' from ingredients where name = 'Tender';
