insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('frango-assado-com-batatas', 6, 'Frango assado com batatas', 'salgado', 'carnes-e-pratos-principais', 'principal', '5 a 6 pessoas', 6, '20 min', '1h a 1h15', '["Misture alho, limão, manteiga, azeite, páprica, sal e pimenta.","Espalhe o tempero no frango e deixe marinar na geladeira por pelo menos 2 horas.","Corte as batatas em pedaços grandes e tempere com azeite, sal e alecrim.","Coloque o frango e as batatas em uma assadeira.","Asse até dourar e cozinhar completamente, regando com o caldo.","Confira a temperatura interna da parte mais espessa da ave."]'::jsonb, '["Se a pele dourar antes da hora, cubra só o peito com papel-alumínio."]'::jsonb, '["Batata inglesa: batata-doce ou mandioca pré-cozida."]'::jsonb, 'Geladeira por até 3 dias.', 'Unidade comercial: 1 frango pequeno serve aproximadamente 4–5 como prato principal com acompanhamentos.', 'fotos/frango-assado-com-batatas.webp', 'rascunho');
