insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('frango-recheado-com-farofa', 7, 'Frango recheado com farofa', 'salgado', 'carnes-e-pratos-principais', 'principal', '6 pessoas', 6, '40 min', '1h15 a 1h30', '["Tempere o frango com alho, limão, manteiga, páprica, sal e pimenta. Mantenha refrigerado.","Frite o bacon, acrescente a cebola e a manteiga.","Junte os ovos, mexa até cozinhar e adicione a farinha aos poucos.","Finalize com cheiro-verde e deixe a farofa esfriar.","Recheie o frango sem compactar demais e feche a abertura com palitos ou barbante culinário.","Asse até que tanto a ave quanto o recheio atinjam temperatura segura."]'::jsonb, '["Recheio frio e solto: ele precisa aquecer junto com a ave para ficar seguro.","A farinha para a farofa do recheio entra junto com os demais ingredientes da lista."]'::jsonb, '["Bacon: linguiça ou calabresa."]'::jsonb, 'Retire o recheio para guardar. Geladeira por até 2 dias.', 'Recheio deve entrar frio; não usar recheio em excesso. Para mais pessoas, assar mais unidades.', 'fotos/frango-recheado-com-farofa.webp', 'rascunho');
