insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('bacalhau-ao-forno', 8, 'Bacalhau ao forno', 'salgado', 'carnes-e-pratos-principais', 'principal', '6 pessoas', 6, '40 min + dessalga (24 a 48 h)', '35 a 45 min', '["Dessalgue o bacalhau sob refrigeração, trocando a água conforme a espessura e as orientações do produto.","Cozinhe as batatas até ficarem macias, mas firmes.","Em um refratário, faça camadas de batata, cebola, pimentões e bacalhau.","Distribua alho, azeitonas e azeite.","Leve ao forno até o bacalhau ficar cozido e os vegetais dourados.","Finalize com ovos cozidos e cheiro-verde."]'::jsonb, '["O bacalhau ganha cerca de 25% de peso ao dessalgar: para 1 kg dessalgado, compre cerca de 800 g salgado (a lista já faz essa conta)."]'::jsonb, '["Bacalhau Porto (mais caro) por saithe ou desfiado (mais barato)."]'::jsonb, 'Geladeira por até 2 dias.', 'Peso é de bacalhau já dessalgado. Se comprar salgado, o peso e processo mudam.', 'fotos/bacalhau-ao-forno.webp', 'rascunho');
insert into recipe_ingredients (recipe_id, ingredient_id, qty, unit, note, grp, sort, scale_rule) select 'bacalhau-ao-forno', id, 1, 'kg', null, null, 0, 'linear' from ingredients where name = 'Bacalhau dessalgado em postas';
