insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('peixe-assado-com-ervas-e-limao', 9, 'Peixe assado com ervas e limão', 'salgado', 'carnes-e-pratos-principais', 'principal', '5 a 6 pessoas', 6, '20 min + 30 min de tempero', '35 a 45 min', '["Faça cortes superficiais nos dois lados do peixe.","Tempere com alho, limão, sal, pimenta e azeite.","Recheie a cavidade com ervas e algumas rodelas de limão.","Forre uma assadeira com cebola e tomate e acomode o peixe.","Asse em forno preaquecido até a carne ficar opaca e se soltar facilmente.","Finalize com ervas frescas e limão."]'::jsonb, '["Prefira peixes de carne firme: tilápia inteira, pescada, robalo ou tainha."]'::jsonb, '["Peixe inteiro: filés grossos, com tempo de forno de 20 a 25 minutos."]'::jsonb, 'Consumir no mesmo dia ou em até 1 dia na geladeira.', 'Peixe inteiro inclui cabeça e espinhas; para filé, usar porção diferente.', 'fotos/peixe-assado-com-ervas-e-limao.webp', 'rascunho');
