insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('carne-assada-ao-molho-madeira', 10, 'Carne assada ao molho madeira', 'salgado', 'carnes-e-pratos-principais', 'principal', '6 pessoas', 6, '20 min', '50 min a 1h na pressão (ou 2h em panela comum)', '["Tempere a carne com alho, sal, pimenta e louro.","Aqueça o óleo e sele todos os lados da peça.","Acrescente cebola e água ou caldo. Cozinhe na pressão até ficar macia, conforme o corte.","Retire a carne e reserve o caldo.","Em outra panela, derreta a manteiga, acrescente a farinha e mexa.","Adicione o vinho e o caldo aos poucos até formar um molho.","Junte os champignons, fatie a carne e cubra com o molho."]'::jsonb, '["Na panela de pressão, o cozimento cai para 40 a 50 minutos após pegar pressão."]'::jsonb, '["Vinho tinto: suco de uva integral com 1 colher de vinagre.","Champignon: pode omitir."]'::jsonb, 'Geladeira por até 4 dias; congela bem com o molho.', 'Corte e método alteram tempo; validar maciez e temperatura conforme corte.', 'fotos/carne-assada-ao-molho-madeira.webp', 'rascunho');
