insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('costela-suina-assada', 11, 'Costela suína assada', 'salgado', 'carnes-e-pratos-principais', 'principal', '5 a 6 pessoas', 6, '15 min + 4 a 12 h de tempero', '2h a 2h30', '["Misture limão, alho, mostarda, azeite e temperos.","Espalhe sobre a costela e deixe marinar na geladeira por pelo menos 4 horas.","Coloque em assadeira, cubra com papel-alumínio e asse em temperatura moderada até amaciar.","Retire o papel e deixe dourar.","Regue com o próprio caldo e sirva."]'::jsonb, '["A costela está pronta quando a carne solta do osso com facilidade."]'::jsonb, '["Açúcar mascavo: mel ou açúcar comum."]'::jsonb, 'Geladeira por até 3 dias.', 'Osso reduz rendimento. O tempo varia conforme espessura; não usar apenas relógio para avaliar ponto.', 'fotos/costela-suina-assada.webp', 'rascunho');
