insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('costela-bovina-assada', 12, 'Costela bovina assada', 'salgado', 'carnes-e-pratos-principais', 'principal', '6 pessoas', 6, '15 min', '4h a 5h', '["Esfregue alho, sal e pimenta na costela.","Disponha a carne sobre uma cama de cebola, com alecrim e louro.","Acrescente a água e cubra muito bem com papel-alumínio.","Asse em temperatura baixa por várias horas, até ficar macia.","Retire o papel e aumente a temperatura para dourar.","Descanse alguns minutos antes de cortar."]'::jsonb, '["É um prato de forno longo: planeje para não disputar forno com o peru ou o chester."]'::jsonb, '["Costela minga: rende mais carne e custa pouco mais."]'::jsonb, 'Geladeira por até 4 dias; congela desfiada.', 'Alto teor de osso; estimativa de compra maior que carne desossada. Validar rendimento real.', 'fotos/costela-bovina-assada.webp', 'rascunho');
