insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('arroz-a-grega', 13, 'Arroz à grega', 'salgado', 'arroz-farofas-e-acompanhamentos', 'acompanhamento', '6 pessoas', 6, '15 min', '25 min', '["Refogue a cebola e o alho no azeite.","Acrescente o arroz e o sal, mexendo por alguns minutos.","Adicione água e cozinhe até o arroz ficar macio.","Em outra panela, refogue cenoura, pimentões, ervilha e milho.","Misture os vegetais, as passas e o arroz pronto.","Finalize com cheiro-verde."]'::jsonb, '["Pode cozinhar o arroz na véspera e misturar os legumes na hora."]'::jsonb, '["Passas: omita ou troque por milho.","Legumes frescos: seleta de legumes em lata."]'::jsonb, 'Geladeira por até 3 dias.', 'Água varia conforme arroz e panela; testar textura. Rendimento aproximado 6 porções de acompanhamento.', 'fotos/arroz-a-grega.webp', 'rascunho');
