insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('arroz-natalino-com-castanhas', 14, 'Arroz natalino com castanhas', 'salgado', 'arroz-farofas-e-acompanhamentos', 'acompanhamento', '6 pessoas', 6, '15 min', '25 min', '["Refogue cebola e alho na manteiga.","Acrescente o arroz e mexa.","Adicione água ou caldo e cozinhe até ficar macio.","Em uma frigideira, doure levemente as castanhas e as nozes.","Misture ao arroz junto com damasco e passas.","Finalize com salsinha."]'::jsonb, '["Castanhas tostadas na hora ficam mais crocantes."]'::jsonb, '["Castanha-de-caju: amendoim torrado sem sal.","Damasco: maçã em cubinhos."]'::jsonb, 'Geladeira por até 3 dias.', 'Castanhas podem ser substituídas por sementes para reduzir custo; observar alergênicos.', 'fotos/arroz-natalino-com-castanhas.webp', 'rascunho');
