insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('arroz-com-brocolis', 15, 'Arroz com brócolis', 'salgado', 'arroz-farofas-e-acompanhamentos', 'acompanhamento', '6 pessoas', 6, '10 min', '25 min', '["Separe os floretes e pique os talos mais macios do brócolis.","Refogue cebola e alho no azeite.","Acrescente o arroz, a água e o sal.","Quando estiver quase cozido, incorpore os floretes de brócolis.","Termine o cozimento em fogo baixo.","Solte os grãos com um garfo e sirva."]'::jsonb, '["Use também os talos descascados e picados: rende mais e evita desperdício."]'::jsonb, '["Brócolis fresco: brócolis congelado."]'::jsonb, 'Geladeira por até 2 dias.', 'Não cozinhar demais o brócolis; ajustar água se usar talos.', 'fotos/arroz-com-brocolis.webp', 'rascunho');
