insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('farofa-de-bacon-e-cebola', 16, 'Farofa de bacon e cebola', 'salgado', 'arroz-farofas-e-acompanhamentos', 'acompanhamento', '6 pessoas', 6, '10 min', '15 min', '["Frite o bacon até dourar.","Acrescente a cebola e refogue até ficar macia.","Junte alho e manteiga.","Adicione a farinha aos poucos, mexendo para incorporar.","Ajuste sal e pimenta.","Finalize com cheiro-verde."]'::jsonb, '["Prove antes de pôr sal: o bacon já salga bastante."]'::jsonb, '["Bacon: calabresa ou paio."]'::jsonb, 'Pote fechado em temperatura ambiente por 1 dia, ou geladeira por até 5 dias.', 'Bacon já contém sal; provar antes de acrescentar sal.', 'fotos/farofa-de-bacon-e-cebola.webp', 'rascunho');
