insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('farofa-de-banana', 17, 'Farofa de banana', 'salgado', 'arroz-farofas-e-acompanhamentos', 'acompanhamento', '6 pessoas', 6, '10 min', '15 min', '["Corte as bananas em rodelas ou cubos.","Doure as bananas em parte da manteiga e reserve.","Refogue a cebola no restante da manteiga e no azeite.","Adicione a farinha aos poucos.","Misture delicadamente as bananas.","Acerte o sal e finalize com cheiro-verde."]'::jsonb, '["Use banana-da-terra firme, ainda com casca amarela."]'::jsonb, '["Banana-da-terra: banana-nanica firme."]'::jsonb, 'Melhor no dia; geladeira por até 2 dias.', 'Banana madura demais pode desmanchar; usar firme.', 'fotos/farofa-de-banana.webp', 'rascunho');
