insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('farofa-de-calabresa-com-ovos', 18, 'Farofa de calabresa com ovos', 'salgado', 'arroz-farofas-e-acompanhamentos', 'acompanhamento', '6 pessoas', 6, '10 min', '15 min', '["Corte a calabresa em cubos e frite até dourar.","Acrescente a cebola e o alho.","Em uma parte livre da panela, prepare os ovos mexidos.","Misture tudo e adicione a manteiga.","Coloque a farinha aos poucos, mexendo bem.","Finalize com cheiro-verde."]'::jsonb, '["Calabresa já tem sal: prove antes de temperar."]'::jsonb, '["Calabresa: linguiça toscana ou bacon."]'::jsonb, 'Geladeira por até 3 dias.', 'Controlar sal por causa da calabresa.', 'fotos/farofa-de-calabresa-com-ovos.webp', 'rascunho');
