insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('farofa-natalina-com-frutas-secas', 19, 'Farofa natalina com frutas secas', 'salgado', 'arroz-farofas-e-acompanhamentos', 'acompanhamento', '6 pessoas', 6, '10 min', '10 min', '["Frite o bacon até dourar.","Acrescente a cebola e a manteiga.","Adicione damasco, passas, ameixas e castanhas.","Incorpore a farinha gradualmente.","Mexa até ficar levemente tostada.","Ajuste o sal e finalize com cheiro-verde."]'::jsonb, '["Fica ótima como acompanhamento do peru ou do tender."]'::jsonb, '["Damasco e castanha (mais caros): uva-passa e amendoim."]'::jsonb, 'Pote fechado na geladeira por até 5 dias.', 'Frutas e castanhas são itens de maior custo; permitir omissões/substituições.', 'fotos/farofa-natalina-com-frutas-secas.webp', 'rascunho');
