insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('batata-gratinada', 20, 'Batata gratinada', 'salgado', 'arroz-farofas-e-acompanhamentos', 'acompanhamento', '6 pessoas', 6, '20 min', '45 min a 1h', '["Descasque as batatas e corte em rodelas finas.","Misture leite, creme de leite, alho, sal, pimenta e noz-moscada.","Unte um refratário e distribua as batatas em camadas.","Despeje a mistura cremosa.","Cubra com muçarela e parmesão.","Asse até as batatas ficarem macias e a superfície dourada."]'::jsonb, '["Fatias finas e iguais cozinham por igual: use o lado fatiador do ralador."]'::jsonb, '["Creme de leite: mais leite com 1 colher de amido."]'::jsonb, 'Geladeira por até 3 dias; reaqueça no forno.', 'Espessura das fatias determina tempo; testar cozimento no centro.', 'fotos/batata-gratinada.webp', 'rascunho');
