insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('pure-de-mandioquinha', 21, 'Purê de mandioquinha', 'salgado', 'arroz-farofas-e-acompanhamentos', 'acompanhamento', '6 pessoas', 6, '15 min', '25 min', '["Descasque e corte a mandioquinha em pedaços.","Cozinhe em água até ficar bem macia.","Escorra e amasse ainda quente.","Leve à panela com manteiga e leite.","Mexa até ficar cremoso.","Acrescente creme de leite, sal, pimenta e noz-moscada."]'::jsonb, '["Adicione o leite aos poucos: a mandioquinha varia de umidade."]'::jsonb, '["Mandioquinha: batata ou mandioca."]'::jsonb, 'Geladeira por até 2 dias.', 'Ajustar leite aos poucos conforme umidade da raiz.', 'fotos/pure-de-mandioquinha.webp', 'rascunho');
