insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('salpicao-de-frango', 22, 'Salpicão de frango', 'salgado', 'saladas-e-pratos-frios', 'salada', '6 pessoas', 6, '30 min + 1 h de geladeira', '25 min (frango)', '["Cozinhe o frango com alho, cebola e sal. Espere esfriar e desfie.","Misture frango, cenoura, milho, ervilha, maçã e passas.","Acrescente maionese, creme de leite e limão.","Tempere e misture até ficar uniforme.","Leve à geladeira por pelo menos 1 hora.","Coloque a batata palha somente na hora de servir."]'::jsonb, '["A lista de compras já converte o frango cozido para peito cru (cerca de 30% a mais)."]'::jsonb, '["Peito de frango: sobras de chester ou peru.","Salsão: omita."]'::jsonb, 'Sempre na geladeira, por até 2 dias. Não deixe mais de 2 horas fora.', 'Manter refrigerado até servir; não deixar em temperatura ambiente por longos períodos.', 'fotos/salpicao-de-frango.webp', 'rascunho');
