insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('maionese-de-batata', 23, 'Maionese de batata', 'salgado', 'saladas-e-pratos-frios', 'salada', '6 pessoas', 6, '20 min + 1 h de geladeira', '15 min', '["Descasque as batatas e a cenoura e corte em cubos.","Cozinhe separadamente até ficarem macias, mas sem desmanchar.","Espere esfriar e misture com milho e ervilha.","Acrescente maionese, mostarda e limão.","Incorpore os ovos cozidos picados.","Ajuste os temperos e mantenha refrigerada até servir."]'::jsonb, '["Nunca misture a maionese com batata quente."]'::jsonb, '["Ervilha fresca: em lata, escorrida."]'::jsonb, 'Sempre na geladeira, por até 2 dias. Não deixe mais de 2 horas fora.', 'Misturar maionese somente com legumes frios; manter cadeia fria.', 'fotos/maionese-de-batata.webp', 'rascunho');
