insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('salada-tropical', 25, 'Salada tropical', 'salgado', 'saladas-e-pratos-frios', 'salada', '6 pessoas', 6, '20 min', 'Não vai ao fogo', '["Higienize e seque as folhas.","Corte manga e abacaxi em cubos.","Corte os tomates ao meio.","Distribua as folhas em uma travessa e acrescente frutas, cenoura e tomates.","Misture os ingredientes do molho.","Tempere e coloque as castanhas pouco antes de servir."]'::jsonb, '["Molho separado evita folhas murchas."]'::jsonb, '["Manga: mamão ou uva sem semente.","Tomate-cereja: tomate comum em cubos."]'::jsonb, 'Monte no dia; folhas sem molho duram 1 dia na geladeira.', 'Frutas podem variar por estação; manter molho separado.', 'fotos/salada-tropical.webp', 'rascunho');
