insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('salada-de-grao-de-bico', 26, 'Salada de grão-de-bico', 'salgado', 'saladas-e-pratos-frios', 'salada', '6 pessoas', 6, '15 min (+ 8 h de molho)', '40 min a 1h (ou 20 min na pressão)', '["Deixe o grão-de-bico de molho por aproximadamente 8 a 12 horas na geladeira.","Descarte a água do molho e cozinhe em água limpa até ficar macio, mas firme.","Escorra e deixe esfriar.","Pique tomate, pepino, cebola e pimentão.","Misture tudo com azeite, limão, sal, pimenta e salsinha.","Mantenha refrigerada até servir."]'::jsonb, '["400 g de grão-de-bico seco rendem cerca de 900 g cozido.","Fica ainda melhor no dia seguinte."]'::jsonb, '["Grão-de-bico seco: 2 latas de grão-de-bico cozido, escorridas."]'::jsonb, 'Geladeira por até 3 dias; fica ainda melhor no dia seguinte.', 'Peso indicado é cozido; rendimento seco depende de hidratação.', 'fotos/salada-de-grao-de-bico.webp', 'rascunho');
