insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('cuscuz-paulista', 27, 'Cuscuz paulista', 'salgado', 'saladas-e-pratos-frios', 'salada', '8 pessoas', 8, '30 min + 1 h para firmar', '20 min', '["Refogue cebola e alho no azeite.","Acrescente pimentão, tomate, milho, ervilha e sardinha.","Adicione molho de tomate, água ou caldo e tempere.","Quando ferver, coloque a farinha aos poucos, mexendo até engrossar.","Unte uma forma e decore o fundo com ovos, tomate e azeitonas.","Coloque a massa, pressione levemente e deixe esfriar antes de desenformar."]'::jsonb, '["Se a massa ficar seca, acrescente um pouco mais de caldo quente."]'::jsonb, '["Sardinha: frango desfiado ou atum."]'::jsonb, 'Geladeira por até 3 dias.', 'A quantidade de líquido depende da farinha; acrescentar gradualmente.', 'fotos/cuscuz-paulista.webp', 'rascunho');
