insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('caponata-de-berinjela', 28, 'Caponata de berinjela', 'salgado', 'saladas-e-pratos-frios', 'salada', '6 pessoas como entrada', 6, '20 min', '40 min', '["Corte berinjelas, pimentões, cebola e tomates em cubos.","Misture com alho, azeitonas, passas, azeite, vinagre e temperos.","Distribua em assadeira.","Asse, mexendo ocasionalmente, até os vegetais ficarem macios.","Deixe esfriar e ajuste os temperos.","Sirva fria ou em temperatura ambiente, com pães e torradas."]'::jsonb, '["Feita na véspera, fica mais saborosa."]'::jsonb, '["Passas: omita."]'::jsonb, 'Pote fechado na geladeira por até 5 dias.', 'Pode ser feita na véspera e refrigerada em recipiente fechado.', 'fotos/caponata-de-berinjela.webp', 'rascunho');
