insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('legumes-assados', 29, 'Legumes assados', 'salgado', 'entradas-e-complementos', 'entrada', '6 pessoas', 6, '20 min', '35 a 45 min', '["Higienize e corte os legumes em pedaços de tamanho semelhante.","Coloque em uma assadeira.","Tempere com azeite, alho, alecrim, tomilho, sal e pimenta.","Misture bem para distribuir o tempero.","Asse em forno preaquecido até os legumes ficarem macios e dourados.","Mexa na metade do tempo para assar uniformemente."]'::jsonb, '["Assadeira lotada cozinha no vapor e não doura: divida em duas se precisar."]'::jsonb, '["Use os legumes mais baratos da semana: abóbora, chuchu e beterraba também funcionam."]'::jsonb, 'Geladeira por até 3 dias.', 'Pode precisar de duas assadeiras para não cozinhar no vapor.', 'fotos/legumes-assados.webp', 'rascunho');
