insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('torta-fria-de-frango', 30, 'Torta fria de frango', 'salgado', 'entradas-e-complementos', 'entrada', '8 pessoas', 8, '30 min + 4 h de geladeira', '25 min (frango)', '["Cozinhe o frango com temperos e desfie.","Misture o frango com cenoura, milho, cebola, maionese, requeijão e cheiro-verde.","Em uma travessa, faça uma camada de pão de forma.","Umedeça levemente com leite e espalhe parte do recheio.","Repita as camadas até terminar os ingredientes.","Cubra com maionese e leve à geladeira por pelo menos 3 horas.","Decore com batata palha pouco antes de servir."]'::jsonb, '["A lista de compras já converte o frango cozido para peito cru (cerca de 30% a mais)."]'::jsonb, '["Frango: atum ou presunto."]'::jsonb, 'Sempre na geladeira, por até 2 dias.', 'Manter refrigerada; acrescentar batata palha perto de servir.', 'fotos/torta-fria-de-frango.webp', 'rascunho');
