insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('empadao-de-frango', 31, 'Empadão de frango', 'salgado', 'entradas-e-complementos', 'entrada', '8 pessoas', 8, '50 min + 30 min de geladeira', '40 a 50 min', '["Misture farinha, sal e manteiga até formar uma farofa úmida.","Acrescente o ovo e, se necessário, um pouco de água gelada. Misture sem sovar e leve à geladeira.","Refogue cebola e alho no azeite.","Acrescente tomate, frango, milho, ervilha e temperos.","Desligue o fogo, incorpore o requeijão e deixe esfriar.","Abra parte da massa e forre uma forma.","Coloque o recheio e cubra com o restante da massa.","Pincele gema e asse até a massa ficar dourada."]'::jsonb, '["Recheio quente derrete a massa: espere esfriar antes de montar."]'::jsonb, '["Requeijão: creme de leite com 1 colher de amido."]'::jsonb, 'Geladeira por até 3 dias; reaqueça no forno.', 'Não trabalhar demais a massa; recheio deve estar frio antes de montar.', 'fotos/empadao-de-frango.webp', 'rascunho');
