insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('quiche-de-alho-poro', 32, 'Quiche de alho-poró', 'salgado', 'entradas-e-complementos', 'entrada', '8 fatias', 8, '40 min + 30 min de geladeira', '50 min', '["Misture farinha, manteiga, ovo e sal até formar uma massa uniforme.","Leve à geladeira por 30 minutos.","Abra a massa em uma forma e faça pequenos furos com um garfo.","Pré-asse por aproximadamente 10 minutos.","Refogue o alho-poró no azeite até amaciar.","Misture ovos, creme de leite, queijo e temperos.","Espalhe o alho-poró sobre a massa e despeje o creme.","Asse até o recheio firmar e a superfície dourar."]'::jsonb, '["Pode ser servida morna ou fria."]'::jsonb, '["Alho-poró: cebola caramelizada ou espinafre."]'::jsonb, 'Geladeira por até 3 dias.', 'Deixar repousar antes de cortar; pode servir morna ou fria.', 'fotos/quiche-de-alho-poro.webp', 'rascunho');
