insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('bolinho-de-bacalhau', 33, 'Bolinho de bacalhau', 'salgado', 'entradas-e-complementos', 'entrada', 'aproximadamente 25 unidades', 8, '40 min (+ dessalga)', '20 min (fritura)', '["Cozinhe o bacalhau e desfie, retirando espinhas e pele.","Cozinhe as batatas até ficarem macias.","Amasse as batatas até formar um purê firme.","Misture o bacalhau, o purê, o ovo, a cebola e a salsinha.","Tempere com pimenta e noz-moscada.","Modele os bolinhos com duas colheres ou com as mãos.","Frite em óleo quente até dourar e escorra em papel absorvente."]'::jsonb, '["Teste fritando um bolinho primeiro. Se abrir, junte mais farinha."]'::jsonb, '["Bacalhau desfiado (mais barato) funciona bem aqui."]'::jsonb, 'Crus, congelam por até 2 meses: frite direto do congelador.', 'Bacalhau já dessalgado; ajustar sal somente após provar.', 'fotos/bolinho-de-bacalhau.webp', 'rascunho');
