insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('bruschetta-de-tomate', 34, 'Bruschetta de tomate', 'salgado', 'entradas-e-complementos', 'entrada', '6 pessoas, aproximadamente 12 unidades', 6, '15 min', '10 min', '["Corte a baguete em fatias.","Regue com um pouco de azeite e leve ao forno até dourar levemente.","Corte os tomates em cubinhos e retire o excesso de sementes e líquido.","Misture tomate, alho picado, azeite, manjericão, sal e pimenta.","Distribua a mistura sobre as fatias de pão.","Finalize com manjericão fresco e sirva imediatamente."]'::jsonb, '["Monte só na hora para o pão não amolecer."]'::jsonb, '["Manjericão: orégano."]'::jsonb, 'Pão tostado em pote fechado por 2 dias; tomate temperado na geladeira por 1 dia.', 'Montar no último momento para não amolecer o pão.', 'fotos/bruschetta-de-tomate.webp', 'rascunho');
