insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('pate-de-atum', 35, 'Patê de atum', 'salgado', 'entradas-e-complementos', 'entrada', '6 pessoas como entrada', 6, '10 min + 30 min de geladeira', 'Não vai ao fogo', '["Escorra bem o atum.","Coloque em uma tigela e desfie com um garfo.","Acrescente maionese e requeijão.","Misture cenoura, cebola e cheiro-verde.","Tempere com limão, sal e pimenta.","Leve à geladeira por pelo menos 30 minutos.","Sirva com torradas, pães ou biscoitos salgados."]'::jsonb, '["Fica mais cremoso batido no processador."]'::jsonb, '["Cream cheese: requeijão.","Atum: sardinha."]'::jsonb, 'Geladeira por até 2 dias.', 'Manter refrigerado e usar utensílios limpos.', 'fotos/pate-de-atum.webp', 'rascunho');
