insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('pao-recheado-com-queijo-e-ervas', 36, 'Pão recheado com queijo e ervas', 'salgado', 'entradas-e-complementos', 'entrada', '6 pessoas', 6, '40 min + 1h30 de fermentação', '25 a 30 min', '["Misture fermento, açúcar e água morna.","Acrescente farinha, sal e azeite.","Sove até obter uma massa lisa e deixe crescer até dobrar de volume.","Misture muçarela, parmesão, alho, manteiga, orégano e salsinha.","Abra a massa, espalhe o recheio e enrole ou modele em formato de pão.","Deixe crescer novamente por aproximadamente 30 minutos.","Asse em forno preaquecido até dourar e o queijo derreter."]'::jsonb, '["Sirva quente, no centro da mesa, para cada um puxar o seu pedaço."]'::jsonb, '["Pão italiano: baguete ou pão sírio."]'::jsonb, 'Melhor na hora; geladeira por 1 dia.', 'Recheio pode ser ajustado; servir quente.', 'fotos/pao-recheado-com-queijo-e-ervas.webp', 'rascunho');
