insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('pave-de-chocolate', 1, 'Pavê de chocolate', 'sobremesa', 'paves-e-sobremesas-de-travessa', 'sobremesa', '8 pessoas', 8, '30 min + 4 h de geladeira', '10 min', '["Dissolva o amido no leite frio.","Acrescente leite condensado e chocolate em pó.","Leve ao fogo baixo, mexendo até engrossar.","Desligue e misture o creme de leite.","Em uma travessa, alterne camadas de creme e biscoitos rapidamente umedecidos no leite.","Finalize com chocolate derretido ou raspas.","Refrigere por pelo menos 4 horas."]'::jsonb, '["Biscoito encharcado desmancha: só um mergulho rápido no leite."]'::jsonb, '["Chocolate em pó: cacau em pó com 1 colher a mais de açúcar."]'::jsonb, 'Geladeira por até 3 dias.', 'Manter refrigerado; usar chocolate em pó, não confundir com achocolatado.', 'fotos/pave-de-chocolate.webp', 'rascunho');
