insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('pave-de-bis', 2, 'Pavê de Bis', 'sobremesa', 'paves-e-sobremesas-de-travessa', 'sobremesa', '8 pessoas', 8, '30 min + 4 h de geladeira', '10 min', '["Misture leite condensado, leite, amido e gemas.","Leve ao fogo baixo, mexendo até engrossar.","Desligue e incorpore uma caixa de creme de leite.","Pique uma parte do Bis e reserve o restante para a montagem.","Alterne creme e pedaços de Bis em uma travessa.","Derreta o chocolate e misture com o creme de leite para fazer a ganache.","Espalhe por cima, decore com Bis e leve à geladeira por pelo menos 4 horas."]'::jsonb, '["O chocolate da decoração entra só no final para continuar crocante."]'::jsonb, '["Wafer de chocolate de marca própria do mercado no lugar do chocolate de marca."]'::jsonb, 'Geladeira por até 3 dias.', 'Adicionar parte do Bis perto de servir para preservar crocância.', 'fotos/pave-de-bis.webp', 'rascunho');
