insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('pave-de-morango', 3, 'Pavê de morango', 'sobremesa', 'paves-e-sobremesas-de-travessa', 'sobremesa', '8 pessoas', 8, '30 min + 4 h de geladeira', '10 min', '["Dissolva o amido no leite e misture com leite condensado e gemas.","Cozinhe em fogo baixo até engrossar.","Desligue e misture o creme de leite.","Higienize os morangos, seque bem e corte em pedaços.","Monte camadas de creme, biscoitos umedecidos e morangos.","Finalize com creme e chocolate branco.","Mantenha refrigerado e consuma preferencialmente em até 24 horas, devido à fruta fresca."]'::jsonb, '["Prepare na véspera, mas não com mais de um dia de antecedência: o morango solta água."]'::jsonb, '["Morango fresco: morango congelado, escorrido, só nas camadas internas."]'::jsonb, 'Geladeira por até 2 dias.', 'Morangos frescos soltam água; preparar preferencialmente no dia anterior, não muitos dias antes.', 'fotos/pave-de-morango.webp', 'rascunho');
