insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('pave-de-amendoim', 4, 'Pavê de amendoim', 'sobremesa', 'paves-e-sobremesas-de-travessa', 'sobremesa', '8 pessoas', 8, '30 min + 4 h de geladeira', '10 min', '["Dissolva o amido no leite e misture o leite condensado.","Leve ao fogo até engrossar.","Desligue e acrescente o creme de leite.","Incorpore metade do amendoim ao creme.","Monte camadas de creme e biscoitos umedecidos.","Finalize com o restante do amendoim triturado.","Leve à geladeira por pelo menos 4 horas."]'::jsonb, '["Contém amendoim: avise os convidados com alergia."]'::jsonb, '["Amendoim: paçoca esfarelada (dispensa parte do açúcar do creme)."]'::jsonb, 'Geladeira por até 3 dias.', 'Atenção a alergia a amendoim; informar no cadastro da receita.', 'fotos/pave-de-amendoim.webp', 'rascunho');
