insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('bombom-de-uva-na-travessa', 5, 'Bombom de uva na travessa', 'sobremesa', 'paves-e-sobremesas-de-travessa', 'sobremesa', '8 pessoas', 8, '30 min + 3 a 4 h de geladeira', '15 min', '["Lave as uvas e seque muito bem. Retire os cabinhos.","Em uma panela, coloque leite condensado e manteiga.","Mexa em fogo baixo até formar um creme consistente, mas ainda macio.","Desligue e misture uma caixa de creme de leite. Deixe esfriar.","Distribua as uvas em uma travessa e cubra com o creme branco.","Derreta o chocolate e misture com a outra caixa de creme de leite.","Espalhe a ganache por cima e refrigere até firmar."]'::jsonb, '["Uva molhada deixa o creme aguado: seque muito bem."]'::jsonb, '["Chocolate meio amargo: chocolate ao leite ou cobertura fracionada."]'::jsonb, 'Geladeira por até 2 dias.', 'Uvas devem estar completamente secas; manter refrigerado.', 'fotos/bombom-de-uva-na-travessa.webp', 'rascunho');
