insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('pave-de-abacaxi', 6, 'Pavê de abacaxi', 'sobremesa', 'paves-e-sobremesas-de-travessa', 'sobremesa', '8 pessoas', 8, '30 min + 4 h de geladeira', '25 min', '["Cozinhe o abacaxi com o açúcar até ficar macio e liberar o caldo.","Escorra e reserve a fruta. Deixe esfriar.","Dissolva o amido no leite, junte o leite condensado e cozinhe até engrossar.","Desligue e misture o creme de leite.","Monte camadas de creme, biscoito umedecido e abacaxi.","Finalize com creme e coco ralado.","Refrigere por pelo menos 4 horas."]'::jsonb, '["Abacaxi cru talha o creme: cozinhe sempre antes."]'::jsonb, '["Abacaxi fresco: abacaxi em calda, escorrido (dispensa o cozimento longo)."]'::jsonb, 'Geladeira por até 3 dias.', 'Não usar abacaxi cru diretamente em creme lácteo sem tratamento; cozinhar para reduzir acidez e enzimas.', 'fotos/pave-de-abacaxi.webp', 'rascunho');
