insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('rabanada-tradicional', 7, 'Rabanada tradicional', 'sobremesa', 'sobremesas-tradicionais-de-natal', 'sobremesa', '6 pessoas, aproximadamente 12 fatias', 6, '15 min', '20 min', '["Corte o pão em fatias de aproximadamente 2 cm.","Misture leite, leite condensado e baunilha.","Passe as fatias rapidamente nessa mistura.","Em outro recipiente, bata os ovos.","Passe as fatias nos ovos e frite em óleo quente, sem sobrecarregar a panela.","Escorra em papel absorvente.","Misture açúcar e canela e passe as rabanadas ainda mornas."]'::jsonb, '["Pão de um ou dois dias absorve sem desmanchar."]'::jsonb, '["Pão francês amanhecido no lugar da baguete."]'::jsonb, 'Melhor no dia. Em pote fechado, até 2 dias.', 'Óleo deve estar quente sem queimar; não encharcar o pão.', 'fotos/rabanada-tradicional.webp', 'rascunho');
