insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('rabanada-assada', 8, 'Rabanada assada', 'sobremesa', 'sobremesas-tradicionais-de-natal', 'sobremesa', '6 pessoas, aproximadamente 12 fatias', 6, '15 min', '25 min', '["Corte o pão em fatias.","Misture leite, leite condensado e baunilha.","Umedeça as fatias rapidamente e passe nos ovos batidos.","Disponha em assadeira untada com manteiga.","Pincele levemente com manteiga derretida.","Asse em forno preaquecido a 200 °C, virando na metade do tempo, até dourar.","Passe na mistura de açúcar e canela."]'::jsonb, '["Menos óleo e menos sujeira: boa opção para fazer em quantidade."]'::jsonb, '["Manteiga: margarina."]'::jsonb, 'Pote fechado por até 2 dias.', 'Tempo depende da espessura; assar até centro firme.', 'fotos/rabanada-assada.webp', 'rascunho');
