insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('manjar-de-coco-com-ameixa', 9, 'Manjar de coco com ameixa', 'sobremesa', 'sobremesas-tradicionais-de-natal', 'sobremesa', '8 a 10 pessoas', 10, '20 min + 6 h de geladeira', '25 min', '["Dissolva o amido em parte do leite frio.","Misture o restante do leite, leite de coco, leite condensado e coco ralado.","Leve ao fogo baixo, mexendo sempre até engrossar bem.","Despeje em forma levemente umedecida e deixe esfriar.","Refrigere por pelo menos 4 horas.","Para a calda, cozinhe açúcar, água, ameixas e canela até formar uma calda levemente espessa.","Deixe esfriar, desenforme o manjar e cubra com a calda."]'::jsonb, '["Forma molhada com água fria ajuda a desenformar."]'::jsonb, '["Ameixa preta: calda de goiabada."]'::jsonb, 'Geladeira por até 4 dias.', 'Desenformar somente bem gelado.', 'fotos/manjar-de-coco-com-ameixa.webp', 'rascunho');
