insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('pudim-de-panetone', 10, 'Pudim de panetone', 'sobremesa', 'sobremesas-tradicionais-de-natal', 'sobremesa', '8 pessoas', 8, '20 min + 4 h de geladeira', '1h a 1h15', '["Derreta o açúcar até formar um caramelo dourado.","Acrescente cuidadosamente a água quente e mexa até dissolver os torrões.","Espalhe a calda em uma forma de pudim.","Bata leite condensado, leite, ovos e baunilha.","Distribua os pedaços de panetone na forma e despeje a mistura.","Acrescente passas, se desejar.","Asse em banho-maria, coberto com papel-alumínio, até firmar.","Deixe esfriar e refrigere antes de desenformar."]'::jsonb, '["Ótimo para aproveitar o panetone que sobrou do ano."]'::jsonb, '["Panetone: chocotone ou pão doce."]'::jsonb, 'Geladeira por até 4 dias.', 'Banho-maria e forno variam; testar ponto com lâmina quase limpa.', 'fotos/pudim-de-panetone.webp', 'rascunho');
