insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('pudim-de-leite-condensado', 11, 'Pudim de leite condensado', 'sobremesa', 'pudins-mousses-e-sobremesas-geladas', 'sobremesa', '8 a 10 pessoas', 10, '15 min + 6 h de geladeira', '1h a 1h20', '["Derreta o açúcar em uma panela até obter caramelo dourado.","Acrescente a água quente cuidadosamente e mexa até dissolver.","Espalhe o caramelo em uma forma de pudim.","Bata leite condensado, leite e ovos no liquidificador.","Despeje na forma caramelizada.","Cubra com papel-alumínio e asse em banho-maria a 180 °C até firmar.","Deixe esfriar e leve à geladeira por pelo menos 6 horas antes de desenformar."]'::jsonb, '["Bater demais cria furinhos: só misture."]'::jsonb, '["Cozinhar na panela de pressão: 40 minutos após pegar pressão, em banho-maria."]'::jsonb, 'Geladeira por até 4 dias.', 'Tempo varia por forma e forno; refrigerar antes de desenformar.', 'fotos/pudim-de-leite-condensado.webp', 'rascunho');
