insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('mousse-de-maracuja', 12, 'Mousse de maracujá', 'sobremesa', 'pudins-mousses-e-sobremesas-geladas', 'sobremesa', '6 pessoas', 6, '15 min + 4 h de geladeira', '5 min (cobertura)', '["Coloque leite condensado, creme de leite e suco no liquidificador.","Bata até formar um creme homogêneo.","Distribua em taças ou em uma travessa.","Leve à geladeira por pelo menos 4 horas.","Decore com a polpa do maracujá antes de servir."]'::jsonb, '["Use o suco concentrado sem diluir: é ele que dá a firmeza."]'::jsonb, '["Suco concentrado: polpa de 4 maracujás coada."]'::jsonb, 'Geladeira por até 3 dias.', 'Usar suco concentrado sem diluir; ajustar acidez e doçura.', 'fotos/mousse-de-maracuja.webp', 'rascunho');
