insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('mousse-de-limao', 13, 'Mousse de limão', 'sobremesa', 'pudins-mousses-e-sobremesas-geladas', 'sobremesa', '6 pessoas', 6, '15 min + 3 h de geladeira', 'Não vai ao fogo', '["Coloque leite condensado e creme de leite no liquidificador.","Bata e acrescente o suco de limão aos poucos.","Continue batendo até engrossar.","Distribua em uma travessa ou taças.","Decore com raspas de limão.","Refrigere por pelo menos 3 horas."]'::jsonb, '["Rale só a parte verde da casca: a parte branca amarga."]'::jsonb, '["Biscoito: pode omitir."]'::jsonb, 'Geladeira por até 3 dias.', 'Suco varia de acidez; adicionar gradualmente e provar.', 'fotos/mousse-de-limao.webp', 'rascunho');
