insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('gelatina-mosaico', 14, 'Gelatina mosaico', 'sobremesa', 'pudins-mousses-e-sobremesas-geladas', 'sobremesa', '8 a 10 pessoas', 10, '30 min + 6 h de geladeira', '10 min', '["Prepare separadamente as quatro gelatinas coloridas, utilizando um pouco menos de água do que o indicado na embalagem para obter cubos firmes.","Leve à geladeira até endurecer.","Corte em cubos e misture delicadamente.","Hidrate e dissolva a gelatina incolor conforme as instruções do fabricante.","Bata leite condensado e creme de leite e acrescente a gelatina dissolvida.","Coloque os cubos coloridos em uma travessa e despeje o creme.","Leve à geladeira até firmar completamente."]'::jsonb, '["Use sabores de cores bem diferentes: o mosaico fica mais bonito."]'::jsonb, '["Creme de leite: iogurte natural."]'::jsonb, 'Geladeira por até 4 dias.', 'Conferir instruções da marca; não reduzir água sem teste de textura.', 'fotos/gelatina-mosaico.webp', 'rascunho');
