insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('bolo-gelado-de-chocolate', 15, 'Bolo gelado de chocolate', 'sobremesa', 'pudins-mousses-e-sobremesas-geladas', 'sobremesa', '12 pedaços', 12, '25 min + 4 h de geladeira', '35 a 40 min', '["Bata ovos, açúcar, óleo e leite.","Acrescente farinha e chocolate em pó, misturando até ficar uniforme.","Incorpore o fermento delicadamente.","Despeje em forma untada e asse a 180 °C até passar no teste do palito.","Misture os ingredientes da calda em uma panela e aqueça até ficar homogêneo.","Fure o bolo ainda morno e espalhe a calda.","Corte em pedaços e refrigere por pelo menos 4 horas."]'::jsonb, '["Embrulhado em porções, fica prático para servir e transportar."]'::jsonb, '["Coco ralado: granulado."]'::jsonb, 'Geladeira por até 4 dias.', 'Tempo de forno depende da assadeira; manter refrigerado após molhar.', 'fotos/bolo-gelado-de-chocolate.webp', 'rascunho');
