insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('chocotone-recheado', 16, 'Chocotone recheado', 'sobremesa', 'sobremesas-especiais', 'sobremesa', '8 a 10 fatias', 10, '30 min + 2 h de geladeira', '15 min', '["Corte uma tampa no topo do chocotone.","Retire parte do miolo, deixando uma camada de massa nas laterais e no fundo.","Em uma panela, misture leite condensado, chocolate picado e manteiga.","Mexa em fogo baixo até obter um brigadeiro cremoso.","Desligue e misture o creme de leite. Deixe esfriar.","Misture parte do miolo ao recheio, se desejar.","Recheie o chocotone e feche com a tampa.","Cubra com chocolate derretido e decore. Refrigere para firmar."]'::jsonb, '["Use o miolo que sobrar para um pudim de panetone."]'::jsonb, '["Chocotone: panetone tradicional."]'::jsonb, 'Geladeira por até 3 dias.', 'Refrigerar por causa do recheio lácteo; informar validade conservadora.', 'fotos/chocotone-recheado.webp', 'rascunho');
