insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('pave-de-panetone', 17, 'Pavê de panetone', 'sobremesa', 'sobremesas-especiais', 'sobremesa', '8 pessoas', 8, '30 min + 4 h de geladeira', '10 min', '["Dissolva o amido no leite e acrescente leite condensado e gemas.","Cozinhe em fogo baixo até engrossar.","Desligue e misture uma caixa de creme de leite.","Em uma travessa, coloque uma camada de creme.","Distribua pedaços de panetone levemente umedecidos no leite.","Repita as camadas até terminar os ingredientes.","Derreta o chocolate e misture com o creme de leite restante.","Cubra o pavê com a ganache e refrigere por pelo menos 4 horas."]'::jsonb, '["Não molhe o panetone: o creme já umedece."]'::jsonb, '["Frutas cristalizadas: uva-passa ou gotas de chocolate."]'::jsonb, 'Geladeira por até 3 dias.', 'Panetone pode absorver bastante creme; montar sem encharcar.', 'fotos/pave-de-panetone.webp', 'rascunho');
