insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('torta-de-chocolate-com-morango', 18, 'Torta de chocolate com morango', 'sobremesa', 'sobremesas-especiais', 'sobremesa', '8 a 10 fatias', 10, '30 min + 3 h de geladeira', '15 min', '["Triture os biscoitos até formar uma farinha.","Misture com a manteiga derretida.","Forre o fundo e as laterais de uma forma de torta, pressionando bem.","Leve ao forno a 180 °C por aproximadamente 10 minutos e deixe esfriar.","Derreta o chocolate e misture o creme de leite e a manteiga.","Despeje a ganache sobre a base fria.","Decore com morangos higienizados e bem secos.","Refrigere até firmar."]'::jsonb, '["Forma de fundo removível facilita desenformar."]'::jsonb, '["Morango: uva ou kiwi."]'::jsonb, 'Geladeira por até 3 dias (sem os morangos).', 'Morango fresco deve ser colocado próximo de servir.', 'fotos/torta-de-chocolate-com-morango.webp', 'rascunho');
