insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('cheesecake-com-frutas-vermelhas', 19, 'Cheesecake com frutas vermelhas', 'sobremesa', 'sobremesas-especiais', 'sobremesa', '10 a 12 fatias', 12, '30 min + 6 h de geladeira', '1h a 1h15', '["Triture os biscoitos e misture com a manteiga.","Pressione no fundo de uma forma de aro removível.","Bata cream cheese, leite condensado, ovos, baunilha, limão e farinha até ficar homogêneo.","Despeje sobre a base.","Asse em forno a 160 °C até o centro ficar firme, mas ainda levemente tremido.","Deixe esfriar e refrigere por pelo menos 6 horas.","Para a cobertura, cozinhe as frutas com açúcar e limão até formar uma calda.","Esfrie e distribua sobre a cheesecake."]'::jsonb, '["Esfriar devagar evita rachaduras."]'::jsonb, '["Frutas vermelhas: geleia de goiaba ou de morango."]'::jsonb, 'Geladeira por até 4 dias.', 'Evitar bater excessivamente; resfriar gradualmente para reduzir rachaduras.', 'fotos/cheesecake-com-frutas-vermelhas.webp', 'rascunho');
