insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('salada-de-frutas-cremosa', 20, 'Salada de frutas cremosa', 'sobremesa', 'sobremesas-especiais', 'sobremesa', '8 pessoas', 8, '25 min', 'Não vai ao fogo', '["Higienize e descasque as frutas que necessitam.","Corte em cubos pequenos e retire sementes e partes não comestíveis.","Regue as maçãs e bananas com suco de limão para retardar o escurecimento.","Misture todas as frutas com o suco de laranja.","Acrescente leite condensado e creme de leite.","Misture delicadamente e mantenha refrigerada até servir."]'::jsonb, '["Banana e maçã escurecem rápido: corte por último."]'::jsonb, '["Use as frutas da estação mais baratas na semana."]'::jsonb, 'Sem creme, geladeira por 1 dia; com creme, consumir no dia.', 'Frutas são variáveis; evitar preparar com muita antecedência.', 'fotos/salada-de-frutas-cremosa.webp', 'rascunho');
