insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('torta-holandesa', 21, 'Torta holandesa', 'sobremesa', 'sobremesas-especiais', 'sobremesa', '10 a 12 fatias', 12, '40 min + 6 h de geladeira', '10 min (base)', '["Triture os biscoitos e misture com manteiga.","Forre o fundo de uma forma de aro removível.","Distribua os biscoitos de cobertura em pé nas laterais.","Bata a manteiga até ficar clara e cremosa.","Acrescente o leite condensado aos poucos e depois o creme de leite e a baunilha.","Despeje o creme sobre a base.","Derreta o chocolate e misture com o creme de leite.","Cubra a torta e refrigere por pelo menos 6 horas."]'::jsonb, '["Esta versão não leva ovos crus."]'::jsonb, '["Biscoito coberto de chocolate: biscoito recheado de chocolate."]'::jsonb, 'Geladeira por até 4 dias.', 'Usar ovos pasteurizados se a formulação escolhida incluir ovos crus; esta versão não usa ovos.', 'fotos/torta-holandesa.webp', 'rascunho');
