insert into recipes (id, number, name, kind, category_id, role, yield_text, base_portions, prep_time, cook_time, steps, tips, swaps, storage, scale_notes, image_path, status) values ('brigadeirao', 22, 'Brigadeirão', 'sobremesa', 'sobremesas-especiais', 'sobremesa', '10 a 12 fatias', 12, '15 min + 4 h de geladeira', '1h a 1h15', '["Bata no liquidificador leite condensado, creme de leite, chocolate, ovos, manteiga e açúcar.","Unte uma forma com furo central.","Despeje a mistura e cubra com papel-alumínio.","Asse em banho-maria a 180 °C até ficar firme.","Deixe amornar e desenforme.","Leve à geladeira por aproximadamente 6 horas.","Decore com chocolate granulado antes de servir."]'::jsonb, '["Firme ao toque, mas levemente úmido no centro: está no ponto."]'::jsonb, '["Chocolate em pó: cacau com 1 colher a mais de açúcar."]'::jsonb, 'Geladeira por até 4 dias.', 'Manter refrigerado; tempo varia conforme forma.', 'fotos/brigadeirao.webp', 'rascunho');
