insert into drinks values ('caipirinha', 'Caipirinha', 'Drinks', 'preparada', true, null, null, '{"baseLiters":1.5,"yieldText":"10 copos (cerca de 1,5 L com gelo)","prep":"15 min","ingredients":[{"name":"Limão taiti","qty":10,"unit":"un","note":"médio","group":null},{"name":"Açúcar","qty":20,"unit":"colher-sopa","note":null,"group":null},{"name":"Cachaça","qty":500,"unit":"ml","note":null,"group":null},{"name":"Gelo","qty":2,"unit":"kg","note":null,"group":null}],"steps":["Lave os limões, corte as pontas, retire o miolo branco e corte em 8 pedaços.","Em cada copo, coloque 1 limão picado e 2 colheres de sopa de açúcar e amasse com socador.","Complete com gelo e 50 ml de cachaça.","Misture bem e sirva na hora."],"tips":["Tirar o miolo branco do limão evita o amargo.","Ofereça a versão sem álcool: troque a cachaça por água com gás."],"storage":"Prepare na hora. Limões podem ser cortados com 2 h de antecedência, na geladeira."}'::jsonb);
insert into drinks values ('caipiroska', 'Caipiroska', 'Drinks', 'preparada', true, null, null, '{"baseLiters":1.5,"yieldText":"10 copos (cerca de 1,5 L com gelo)","prep":"15 min","ingredients":[{"name":"Limão taiti","qty":10,"unit":"un","note":"médio","group":null},{"name":"Açúcar","qty":20,"unit":"colher-sopa","note":null,"group":null},{"name":"Vodca","qty":500,"unit":"ml","note":null,"group":null},{"name":"Gelo","qty":2,"unit":"kg","note":null,"group":null}],"steps":["Lave os limões, retire as pontas e o miolo branco e corte em 8 pedaços.","Em cada copo, amasse 1 limão com 2 colheres de sopa de açúcar.","Complete com gelo e 50 ml de vodca.","Misture e sirva na hora."],"tips":["Varie a fruta: morango, maracujá ou abacaxi funcionam com a mesma base."],"storage":"Prepare na hora."}'::jsonb);
insert into drinks values ('suco-laranja', 'Suco de laranja', 'Sucos naturais', 'preparada', false, null, null, '{"baseLiters":2,"yieldText":"2 litros (cerca de 8 copos de 250 ml)","prep":"20 min","ingredients":[{"name":"Laranja-pera","qty":24,"unit":"un","note":"média","group":null},{"name":"Açúcar","qty":null,"unit":null,"note":"opcional, a gosto","group":null},{"name":"Gelo","qty":1,"unit":"kg","note":null,"group":null}],"steps":["Lave as laranjas, corte ao meio e esprema.","Coe se preferir sem bagaço.","Sirva com gelo. Adoce só se precisar."],"tips":["Laranja-pera é a que mais rende suco e costuma ser a mais barata."],"storage":"Geladeira por até 1 dia, em jarra fechada. Melhor feito no dia."}'::jsonb);
insert into drinks values ('suco-abacaxi', 'Suco de abacaxi', 'Sucos naturais', 'preparada', false, null, null, '{"baseLiters":3,"yieldText":"3 litros (cerca de 12 copos)","prep":"15 min","ingredients":[{"name":"Abacaxi","qty":2,"unit":"un","note":"médio, cerca de 1,5 kg cada","group":null},{"name":"Água filtrada","qty":2,"unit":"l","note":null,"group":null},{"name":"Açúcar","qty":null,"unit":null,"note":"opcional, a gosto","group":null},{"name":"Gelo","qty":1,"unit":"kg","note":null,"group":null}],"steps":["Descasque o abacaxi e corte em pedaços, sem o miolo duro.","Bata no liquidificador com a água, em duas levas.","Coe e sirva com gelo."],"tips":["Abacaxi bem maduro dispensa açúcar."],"storage":"Geladeira por até 1 dia."}'::jsonb);
insert into drinks values ('suco-maracuja', 'Suco de maracujá', 'Sucos naturais', 'preparada', false, null, null, '{"baseLiters":2.5,"yieldText":"2,5 litros (cerca de 10 copos)","prep":"15 min","ingredients":[{"name":"Maracujá azedo","qty":6,"unit":"un","note":"grande","group":null},{"name":"Água filtrada","qty":2,"unit":"l","note":null,"group":null},{"name":"Açúcar","qty":12,"unit":"colher-sopa","note":null,"group":null},{"name":"Gelo","qty":1,"unit":"kg","note":null,"group":null}],"steps":["Corte os maracujás e retire a polpa.","Bata a polpa com parte da água por poucos segundos, só para soltar as sementes.","Coe, junte o restante da água e o açúcar e misture.","Sirva gelado."],"tips":["Bater pouco evita triturar as sementes e amargar o suco."],"storage":"Geladeira por até 2 dias."}'::jsonb);
insert into drinks values ('suco-melancia', 'Suco de melancia', 'Sucos naturais', 'preparada', false, null, null, '{"baseLiters":2,"yieldText":"2 litros (cerca de 8 copos)","prep":"15 min","ingredients":[{"name":"Melancia","qty":1,"unit":"un","note":"pequena, cerca de 3 kg","group":null},{"name":"Hortelã","qty":2,"unit":"ramo","note":"opcional","group":null},{"name":"Gelo","qty":1,"unit":"kg","note":null,"group":null}],"steps":["Corte a melancia em cubos e retire as sementes.","Bata no liquidificador sem água, em levas.","Coe se preferir e sirva com gelo e hortelã."],"tips":["Melancia não precisa de água nem de açúcar."],"storage":"Consumir no dia; separa com o tempo, mexa antes de servir."}'::jsonb);
insert into drinks values ('limonada', 'Limonada', 'Sucos naturais', 'preparada', false, null, null, '{"baseLiters":1.6,"yieldText":"1,6 litro (cerca de 6 copos)","prep":"10 min","ingredients":[{"name":"Limão taiti","qty":6,"unit":"un","note":"médio","group":null},{"name":"Água filtrada","qty":1.5,"unit":"l","note":null,"group":null},{"name":"Açúcar","qty":10,"unit":"colher-sopa","note":null,"group":null},{"name":"Gelo","qty":1,"unit":"kg","note":null,"group":null}],"steps":["Lave bem os limões e corte em quatro, retirando as pontas.","Bata com a água e o açúcar por no máximo 5 segundos.","Coe imediatamente e sirva com gelo."],"tips":["Bater mais que 5 segundos deixa a limonada amarga."],"storage":"Consumir em até 2 horas."}'::jsonb);
insert into drinks values ('suco-abacaxi-hortela', 'Suco de abacaxi com hortelã', 'Sucos naturais', 'preparada', false, null, null, '{"baseLiters":3,"yieldText":"3 litros (cerca de 12 copos)","prep":"15 min","ingredients":[{"name":"Abacaxi","qty":2,"unit":"un","note":"médio","group":null},{"name":"Água filtrada","qty":2,"unit":"l","note":null,"group":null},{"name":"Hortelã","qty":4,"unit":"ramo","note":null,"group":null},{"name":"Açúcar","qty":null,"unit":null,"note":"opcional, a gosto","group":null},{"name":"Gelo","qty":1,"unit":"kg","note":null,"group":null}],"steps":["Descasque o abacaxi e corte em pedaços.","Bata com a água e as folhas de hortelã, em duas levas.","Coe e sirva gelado."],"tips":["Use só as folhas da hortelã: o talo amarga."],"storage":"Geladeira por até 1 dia."}'::jsonb);
