insert into drinks values ('agua-com-limao', 'Água com limão', 'Águas', 'preparada', false, null, null, '{"baseLiters":2,"yieldText":"2 litros","prep":"5 min","ingredients":[{"name":"Água filtrada","qty":2,"unit":"l","note":null,"group":null},{"name":"Limão taiti","qty":2,"unit":"un","note":"médio","group":null},{"name":"Gelo","qty":1,"unit":"kg","note":null,"group":null}],"steps":["Lave os limões e corte em rodelas finas.","Coloque na jarra com a água e o gelo.","Deixe 15 minutos na geladeira antes de servir."],"tips":["Algumas folhas de hortelã deixam ainda mais refrescante."],"storage":"Retire os limões após 4 horas para não amargar."}'::jsonb);
